#!/bin/bash
# Prints the three IP addresses that appear most often in access.log,
# most frequent first. Ties are broken by first appearance in the log.
set -euo pipefail
cd "$(dirname "$0")"

awk '{
    ip = $1
    if (!(ip in count)) {
        first[ip] = NR
    }
    count[ip]++
}
END {
    for (ip in count) {
        print count[ip], first[ip], ip
    }
}' access.log | sort -k1,1nr -k2,2n | head -n 3 | awk '{print $3}'
